 static void eq(String k,double actual,double expected){if(Math.abs(actual-expected)>.02)throw new AssertionError(k+" actual="+actual+" expected="+expected);out.accept("Ultimate PASS "+k+" "+actual);}
 static void equip(List<String> passives,List<String> mods){var owner=(SpellContainerSource.Owner)p;var old=owner.getSpellContainers();var ids=new ArrayList<>(passives);ids.addAll(mods);var container=new net.spell_engine.api.spell.container.SpellContainer(net.spell_engine.api.spell.container.SpellContainer.ContentType.NONE,"","",0,ids);owner.setSpellContainers(new SpellContainerSource.Result(old.activeContainer(),List.of(),passives.stream().map(WarriorUltimatesProbe::spell).toList(),mods.stream().map(WarriorUltimatesProbe::spell).toList(),List.of(new SpellContainerSource.SourcedContainer("ult",ItemStack.EMPTY,container))));owner.spellModifierCache().clear();}
 static LivingEntity mob(double x,double z){var m=EntityTypes.VILLAGER.create(world,EntitySpawnReason.COMMAND);m.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);m.setHealth(1000);m.setPos(x,80,z);m.setNoAi(true);m.setNoGravity(true);world.addFreshEntity(m);return m;}
 static SpellExecution.ImpactContext context(Holder<Spell> h,float channel){return new SpellExecution.ImpactContext(channel,1,null,new SpellPower.Result(h.value().school,10,0,1.5),SpellTarget.FocusMode.DIRECT,0);}
 static void pulse(Holder<Spell> h){SpellImpacts.performImpacts(world,p,p,p,h,h.value().impacts,context(h,.5f),false,null);}
 static double attr(String id){return p.getAttributeValue(BuiltInRegistries.ATTRIBUTE.get(Identifier.parse(id)).orElseThrow());}
 static void clear(){p.removeAllEffects();p.setAbsorptionAmount(0);((net.spell_engine.api.entity.LivingEntityImmunity.Owner)p).getImmunities().clear();p.setHealth(p.getMaxHealth());p.invulnerableTime=0;}
 static void removeCd(String id){((SpellCaster.Player)p).getCooldownManager().remove(Identifier.parse(id));}
 static void start(Holder<Spell> h){((SpellCaster.Player)p).getInteractor().requestClear();((SpellCaster.Player)p).getInteractor().setProcess(new SpellCast.Process(p,h,p.getMainHandItem().getItem(),1,50,world.getGameTime()));}
 public static void run(ServerLevel w,ServerPlayer player,Consumer<String> sink)throws Exception{
  world=w;p=player;out=sink;var owner=(SpellContainerSource.Owner)p;var saved=owner.getSpellContainers();var mode=p.gameMode.getGameModeForPlayer();double attack=p.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();p.setGameMode(GameType.SURVIVAL);p.getAbilities().invulnerable=false;p.setInvulnerable(false);
  for(String f:List.of("clientLoadedTimeoutTimer","waitingForRespawn")){var field=net.minecraft.server.network.ServerGamePacketListenerImpl.class.getDeclaredField(f);field.setAccessible(true);if(field.getType()==int.class)field.setInt(p.connection,0);else field.setBoolean(p.connection,false);}
  try{clear();p.setPos(0,80,0);p.setOnGround(true);p.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(10);berserker();lastStand();healthPassives();momentum();}finally{((SpellCaster.Player)p).getInteractor().requestClear();clear();p.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(attack);p.setGameMode(mode);owner.setSpellContainers(saved);owner.spellModifierCache().clear();}
 }
