  var h=spell("rogues:last_stand");equip(List.of("skill_tree_rpgs:warrior_tier_4_spell_2_modifier_2"),List.of("skill_tree_rpgs:warrior_tier_4_spell_2_root","skill_tree_rpgs:warrior_tier_4_spell_2_modifier_1"));clear();removeCd("rogues:last_stand");start(h);double max=p.getMaxHealth(),scale=attr("minecraft:scale"),taken=attr("spell_engine:damage_taken");
