 static void tasks(){var scheduler=(net.spell_engine.utils.WorldScheduler)world;scheduler.updateScheduledTasks();for(var e:Map.copyOf(scheduler.getScheduledTasks()).entrySet())if(e.getKey()<=world.getGameTime()+1){scheduler.getScheduledTasks().remove(e.getKey());List.copyOf(e.getValue()).forEach(Runnable::run);}}
